-- create "ad_audience_members" table
CREATE TABLE "ad_audience_members" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "audience_id" uuid NOT NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"));
-- create index "adaudiencemember_audience_id_user_id" to table: "ad_audience_members"
CREATE UNIQUE INDEX "adaudiencemember_audience_id_user_id" ON "ad_audience_members" ("audience_id", "user_id");
-- create index "adaudiencemember_user_id" to table: "ad_audience_members"
CREATE INDEX "adaudiencemember_user_id" ON "ad_audience_members" ("user_id");
-- create "ad_custom_audiences" table
CREATE TABLE "ad_custom_audiences" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "name" character varying NOT NULL, "type" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'building', "matched_count" bigint NOT NULL DEFAULT 0, "retention_days" bigint NULL, "description" character varying NOT NULL DEFAULT '', "params" jsonb NOT NULL, "lookalike_source_id" uuid NULL, "lookalike_country_code" character varying NOT NULL DEFAULT '', "lookalike_similarity_percent" bigint NOT NULL DEFAULT 0, "idempotency_key" character varying NOT NULL DEFAULT '', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "adcustomaudience_account_id_created_at" to table: "ad_custom_audiences"
CREATE INDEX "adcustomaudience_account_id_created_at" ON "ad_custom_audiences" ("account_id", "created_at");
-- create index "adcustomaudience_account_id_idempotency_key" to table: "ad_custom_audiences"
CREATE UNIQUE INDEX "adcustomaudience_account_id_idempotency_key" ON "ad_custom_audiences" ("account_id", "idempotency_key") WHERE ((idempotency_key)::text <> ''::text);
-- create "ad_media" table
CREATE TABLE "ad_media" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "uploaded_by" uuid NOT NULL, "file_name" character varying NOT NULL, "mime_type" character varying NOT NULL, "size_bytes" bigint NOT NULL, "kind" character varying NOT NULL, "object_key" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'pending_upload', "width" bigint NOT NULL DEFAULT 0, "height" bigint NOT NULL DEFAULT 0, "duration_seconds" bigint NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "admedia_account_id_created_at" to table: "ad_media"
CREATE INDEX "admedia_account_id_created_at" ON "ad_media" ("account_id", "created_at");
-- create index "admedia_status_created_at" to table: "ad_media"
CREATE INDEX "admedia_status_created_at" ON "ad_media" ("status", "created_at");
-- create "ad_scheduled_reports" table
CREATE TABLE "ad_scheduled_reports" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "created_by" uuid NOT NULL, "name" character varying NOT NULL, "recipients" jsonb NOT NULL, "frequency" character varying NOT NULL, "breakdown" character varying NOT NULL, "metrics" jsonb NOT NULL, "next_send_at" timestamptz NOT NULL, "last_sent_at" timestamptz NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "adscheduledreport_account_id_created_at" to table: "ad_scheduled_reports"
CREATE INDEX "adscheduledreport_account_id_created_at" ON "ad_scheduled_reports" ("account_id", "created_at");
-- create index "adscheduledreport_next_send_at" to table: "ad_scheduled_reports"
CREATE INDEX "adscheduledreport_next_send_at" ON "ad_scheduled_reports" ("next_send_at");
